4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	    
7	    <!-- 網頁標題與描述 (分享時會顯示) -->
8	    <title>幸運轉盤 - 誰是幸運兒？</title>
9	    <meta name="description" content="輸入名單，馬上開始隨機轉盤！適合抽獎、選人、決定午餐吃什麼。">
10	    <meta property="og:title" content="幸運轉盤 - 誰是幸運兒？">
11	    <meta property="og:description" content="輸入名單，馬上開始隨機轉盤！適合抽獎、選人、決定午餐吃什麼。">
12	    <meta property="og:type" content="website">
13	
14	    <!-- 網頁圖標 (Favicon) - 使用 emoji -->
15	    <link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>🎯</text></svg>">
16	
17	    <!-- 引入 Tailwind CSS -->
18	    <script src="https://cdn.tailwindcss.com"></script>
19	    <style>
20	        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;700&display=swap');
21	        body {
22	            font-family: 'Noto Sans TC', sans-serif;
23	        }
24	        canvas {
25	            transition: transform 0.1s;
26	        }
27	    </style>
28	</head>
29	<body class="bg-slate-800 min-h-screen flex flex-col items-center justify-center p-4">
30	
31	    <div class="flex flex-col md:flex-row gap-8 items-start max-w-6xl w-full">
32	        
33	        <!-- 左側：控制區 -->
34	        <div class="bg-white p-6 rounded-xl shadow-2xl w-full md:w-1/3 flex flex-col gap-4">
35	            <h1 class="text-2xl font-bold text-slate-800 text-center border-b pb-2">🎮 設定參賽者</h1>
36	            <p class="text-sm text-gray-500">請輸入名單（每行一個）：</p>
37	            
38	            <textarea id="nameInput" rows="12" class="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none text-slate-700 bg-gray-50 text-sm leading-tight resize-none" placeholder="輸入名字..."></textarea>
39	            
40	            <button onclick="updateWheel()" class="w-full bg-gray-600 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded transition duration-200">
41	                更新轉盤名單
42	            </button>
43	
44	            <div class="mt-4 bg-yellow-50 border-l-4 border-yellow-400 p-4">
45	                <p class="font-bold text-yellow-700">遊戲規則：</p>
46	                <p class="text-sm text-yellow-600">點擊右側的「開始旋轉」，轉盤將隨機轉動，最後指針指到的人即為被選中者。</p>
47	            </div>
48	        </div>
49	
50	        <!-- 右側：轉盤區 -->
51	        <div class="flex-1 flex flex-col items-center justify-center relative w-full md:w-2/3">
52	            <!-- 指針 (CSS繪製) -->
53	            <div class="absolute top-0 left-1/2 transform -translate-x-1/2 -translate-y-2 z-10">
54	                <div class="w-0 h-0 border-l-[20px] border-l-transparent border-r-[20px] border-r-transparent border-t-[40px] border-t-red-600 drop-shadow-lg"></div>
55	            </div>
56	
57	            <div class="relative">
58	                <canvas id="wheelCanvas" width="500" height="500" class="max-w-full h-auto drop-shadow-2xl rounded-full"></canvas>
59	                <!-- 中心裝飾點 -->
60	                <div class="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full shadow-inner border-4 border-gray-200"></div>
61	            </div>
62	
63	            <button id="spinBtn" onclick="spin()" class="mt-8 bg-gradient-to-r from-red-500 to-pink-600 hover:from-red-600 hover:to-pink-700 text-white text-xl font-bold py-4 px-12 rounded-full shadow-lg transform transition hover:scale-105 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed">
64	                開始旋轉！
65	            </button>
66	        </div>
67	    </div>
68	
69	    <!-- 結果彈窗 -->
70	    <div id="resultModal" class="fixed inset-0 bg-black bg-opacity-50 hidden flex items-center justify-center z-50">
71	        <div class="bg-white p-8 rounded-2xl shadow-2xl text-center max-w-sm w-full transform scale-0 transition-transform duration-300" id="modalContent">
72	            <h2 class="text-3xl font-bold text-gray-800 mb-2">🎉 結果出爐！</h2>
73	            <!-- 這裡加了 id 以便我們用程式修改文字 -->
74	            <p id="resultMessage" class="text-gray-500 mb-4 text-lg">被選中的人是：</p>
75	            <div id="winnerName" class="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-purple-600 mb-8 py-2">
76	                測試人員
77	            </div>
78	            <button onclick="closeModal()" class="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-6 rounded-full transition w-full">
79	                確定
80	            </button>
81	        </div>
82	    </div>
83	
84	    <script>
85	        // 設定變數
86	        const canvas = document.getElementById('wheelCanvas');
87	        const ctx = canvas.getContext('2d');
88	        const spinBtn = document.getElementById('spinBtn');
89	        
90	        // 顏色庫 (12色循環)
91	        const colors = [
92	            '#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', 
93	            '#98D8C8', '#F7DC6F', '#BB8FCE', '#F1948A', 
94	            '#82E0AA', '#85C1E9', '#F0B27A', '#D7BDE2'
95	        ];
96	
97	        // 預設名單
98	        let names = [
99	            "王彤", "王坤", "王鶴", "巧巧", "佩君", 
100	            "兆弘", "梨安", "氶浩", "Rose", "茜如", "coco"
101	        ];
102	
103	        // 初始化輸入框
104	        document.getElementById('nameInput').value = names.join('\n');
105	
106	        let startAngle = 0;
107	        let arc = Math.PI * 2 / 12; 
108	        let spinTimeout = null;
109	        let spinAngleStart = 10;
110	        let spinTime = 0;
111	        let spinTimeTotal = 0;
112	        let isSpinning = false;
113	
114	        // 定義有趣的隨機回應語錄
115	        const funMessages = [
116	            "不用懷疑，就是你！👉",
117	            "躲得過初一，躲不過十五...👻",
118	            "恭喜發財！幸運得主是...🎉",
119	            "眾望所歸！大家掌聲鼓勵...👏👏",
120	            "命運女神對你微笑了！✨"
121	        ];
122	
123	        // 繪製轉盤
124	        function drawRouletteWheel() {
125	            arc = Math.PI * 2 / names.length; // 根據名字數量重新計算角度
126	            
127	            // 清空畫布
128	            ctx.clearRect(0, 0, 500, 500);
129	            
130	            const outsideRadius = 240;
131	            const textRadius = 170;
132	            const insideRadius = 50;
133	
134	            ctx.font = 'bold 16px "Noto Sans TC", sans-serif';
135	
136	            for(let i = 0; i < names.length; i++) {
137	                const angle = startAngle + i * arc;
138	                
139	                // 畫扇形
140	                ctx.fillStyle = colors[i % colors.length];
141	                ctx.beginPath();
142	                ctx.arc(250, 250, outsideRadius, angle, angle + arc, false);
143	                ctx.arc(250, 250, insideRadius, angle + arc, angle, true);
144	                ctx.fill();
145	                ctx.save(); // 儲存當前狀態
146	
147	                // 畫文字
148	                ctx.fillStyle = "white";
149	                // 文字陰影讓閱讀更清楚
150	                ctx.shadowColor = "rgba(0,0,0,0.5)";
151	                ctx.shadowBlur = 4;
152	                
153	                ctx.translate(250 + Math.cos(angle + arc / 2) * textRadius, 
154	                              250 + Math.sin(angle + arc / 2) * textRadius);
155	                ctx.rotate(angle + arc / 2 + Math.PI / 2);
156	                const text = names[i];
157	                ctx.fillText(text, -ctx.measureText(text).width / 2, 0);
158	                ctx.restore(); // 恢復狀態
159	            }
160	        }
161	
162	        // 更新名單功能
163	        function updateWheel() {
164	            if(isSpinning) return;
165	            const text = document.getElementById('nameInput').value;
166	            // 過濾空行
167	            const newNames = text.split('\n').filter(n => n.trim() !== '');
168	            if(newNames.length < 2) {
169	                alert("至少需要 2 位參賽者才能玩喔！");
170	                return;
171	            }
172	            names = newNames;
173	            drawRouletteWheel();
174	        }
175	
176	        // 旋轉功能
177	        function spin() {
178	            if(isSpinning) return;
